let categoriaAtual = "";
const itensTratados = [];

function limpar(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

function detectarCategoria(texto) {
  const t = limpar(texto)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  if (t.includes("materiais de consumo")) return "materiais_consumo";
  if (t.includes("material de consumo")) return "materiais_consumo";

  if (t.includes("materiais permanentes")) return "materiais_permanentes";
  if (t.includes("material permanente")) return "materiais_permanentes";
  if (t.includes("materiais permamentes")) return "materiais_permanentes";
  if (t.includes("material permamente")) return "materiais_permanentes";

  if (t.includes("recursos humanos")) return "recursos_humanos";
  if (t.includes("recurso humano")) return "recursos_humanos";

  return "";
}

for (const item of items) {
  const row = item.json;

  // acha automaticamente a coluna principal onde está a descrição/item/categoria
  const chaveDescricao = Object.keys(row).find((k) => {
    const key = String(k || "").toLowerCase();
    return key.includes("planilha") || key.includes("orçament") || key.includes("orcament");
  });

  const textoBase = limpar(chaveDescricao ? row[chaveDescricao] : "");
  const justificativa = limpar(row.col_7 || "");
  const unidade_medida = limpar(row.col_8 || "");
  const valor_unitario = limpar(row.col_9 || "");
  const quantidade = limpar(row.col_10 || "");
  const valor_total = limpar(row.col_11 || "");
  const referencia_preco = limpar(row.col_12 || "");

  if (!textoBase) continue;

  const textoLower = textoBase.toLowerCase();

  // ignora cabeçalhos
  if (textoLower === "descrição do item") continue;
  if (textoLower.includes("planilha orçamentária")) continue;
  if (textoLower.includes("total materiais")) continue;
  if (textoLower === "total") continue;

  // detecta categorias
  const categoriaDetectada = detectarCategoria(textoBase);
  if (categoriaDetectada) {
    categoriaAtual = categoriaDetectada;
    continue;
  }

  // aceita formatos como:
  // 1.1 Caderno...
  // 1.1. Caderno...
  // 2.3 Microfone...
  const matchItem = textoBase.match(/^(\d+\.\d+)\.?\s*(.+)$/);

  if (!matchItem) continue;

  const numero_item = limpar(matchItem[1]);
  const descricao = limpar(matchItem[2]);

  itensTratados.push({
    json: {
      categoria: categoriaAtual,
      item: numero_item,
      descricao,
      justificativa,
      unidade_medida,
      valor_unitario,
      quantidade,
      valor_total,
      referencia_preco
    }
  });
}

return itensTratados;

const itens = items.map(item => item.json);

return [
  {
    json: {
      itens
    }
  }
];

const resposta = $json;

let content = '';

if (resposta.choices?.[0]?.message?.content) {
  content = resposta.choices[0].message.content;
} else if (resposta.data?.choices?.[0]?.message?.content) {
  content = resposta.data.choices[0].message.content;
} else if (resposta.message?.content) {
  content = resposta.message.content;
} else {
  throw new Error('A IA não retornou conteúdo no formato esperado.');
}

const limpar = (txt) => {
  return String(txt || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
};

const limparTextoIA = (txt) => {
  return String(txt || '')
    .replace(/\r/g, '')
    .replace(/\*\*/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

const extrairJson = (txt) => {
  const texto = limpar(txt);

  try {
    return JSON.parse(texto);
  } catch (_) {}

  const inicio = texto.indexOf('{');
  const fim = texto.lastIndexOf('}');

  if (inicio !== -1 && fim !== -1 && fim > inicio) {
    return JSON.parse(texto.slice(inicio, fim + 1));
  }

  throw new Error('Não foi possível extrair um JSON válido da resposta.');
};

const bruto = limpar(content);

let parsed;
let erroParse = '';

try {
  parsed = extrairJson(bruto);
} catch (error) {
  erroParse = error.message || 'A resposta não veio em JSON válido';

  parsed = {
    titulo_projeto: '',
    descricao_projeto: '',
    objetivo_geral: '',
    objetivos_especificos: [],
    justificativa: '',
    metodologia: '',
    publico_direto: '',
    publico_indireto: ''
  };
}

const textoSeguro = (valor) => limparTextoIA(valor);

const tituloProjeto = textoSeguro(parsed.titulo_projeto) || 'Projeto';

const descricaoProjeto =
  textoSeguro(parsed.descricao_projeto) ||
  'A proposta foi estruturada com base nos itens e finalidades previstos na planilha orçamentária, organizando tecnicamente os recursos necessários para a execução das atividades do projeto.';

const objetivoGeral =
  textoSeguro(parsed.objetivo_geral) ||
  'Estruturar e viabilizar a execução do projeto com base nos itens e finalidades previstos na planilha orçamentária.';

const justificativa =
  textoSeguro(parsed.justificativa) ||
  'A proposta se justifica pela necessidade de estruturar adequadamente os recursos materiais, técnicos e operacionais indispensáveis à execução do projeto.';

let objetivosArray = [];

if (Array.isArray(parsed.objetivos_especificos)) {
  objetivosArray = parsed.objetivos_especificos
    .map(o => textoSeguro(o))
    .filter(Boolean);
} else {
  objetivosArray = String(parsed.objetivos_especificos || '')
    .split('\n')
    .map(o => textoSeguro(o).replace(/^[-•\d\.\)\s]+/, '').trim())
    .filter(Boolean);
}

if (!objetivosArray.length) {
  objetivosArray = [
    'Estruturar os recursos necessários para a execução das atividades previstas',
    'Organizar os insumos, equipamentos e materiais de apoio conforme as finalidades apresentadas',
    'Garantir condições técnicas e operacionais adequadas para o desenvolvimento das ações do projeto'
  ];
}

const objetivosFormatados = objetivosArray.map(o => `• ${o}`).join('\n');

let metodologia = textoSeguro(parsed.metodologia);

if (!metodologia) {
  metodologia = '2.5 METODOLOGIA:\nA execução do projeto será organizada a partir dos grupos de ações definidos com base nos itens da planilha orçamentária, garantindo que os recursos previstos estejam vinculados a finalidades práticas de execução.';
}

metodologia = metodologia
  .replace(/\*\*/g, '')
  .replace(/\r/g, '')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

metodologia = metodologia.replace(/^METODOLOGIA:\s*/i, '2.5 METODOLOGIA:\n');

if (!/^2\.5\s+METODOLOGIA:?/i.test(metodologia)) {
  metodologia = `2.5 METODOLOGIA:\n${metodologia}`;
}

metodologia = metodologia
  .replace(/\s+(2\.5\.\d+\s+)/g, '\n\n$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

/* =========================
VALIDAÇÕES DA METODOLOGIA
========================= */

const metodologiaLower = metodologia.toLowerCase();

const temTituloMetodologia = /^2\.5\s+METODOLOGIA:?/i.test(metodologia);
const temGruposNumerados = /2\.5\.1/i.test(metodologia);
const usaSubitensDeProdutos = /2\.5\.\d+\.\d+/i.test(metodologia);

const termosIndesejados = [
  '2.5.1.1',
  '2.5.1.2',
  '2.5.1.3',
  'eixo 1',
  'eixo 2',
  'eixo 3',
  'item 1',
  'item 2',
  'item 3'
];

const termosEncontrados = termosIndesejados.filter(t =>
  metodologiaLower.includes(t.toLowerCase())
);

const metodologiaForaPadrao =
  !temTituloMetodologia ||
  !temGruposNumerados ||
  usaSubitensDeProdutos;

const metodologiaInvalida =
  metodologiaForaPadrao ||
  termosEncontrados.length > 0;

const publicoDireto = textoSeguro(parsed.publico_direto);
const publicoIndireto = textoSeguro(parsed.publico_indireto);

return [
  {
    json: {
      titulo_projeto: tituloProjeto,
      descricao_projeto: descricaoProjeto,
      objetivo_geral: objetivoGeral,
      objetivos_especificos_array: objetivosArray,
      objetivos_especificos: objetivosFormatados,
      justificativa,
      metodologia,
      publico_direto: publicoDireto,
      publico_indireto: publicoIndireto,

      erro_parse: erroParse,

      metodologia_fora_padrao: metodologiaForaPadrao,
      metodologia_invalida: metodologiaInvalida,
      usa_subitens_de_produtos: usaSubitensDeProdutos,
      termos_indesejados_encontrados: termosEncontrados,

      json_resposta: JSON.stringify(parsed),
      resposta_bruta: bruto
    }
  }
];

function formatarMoedaBR(valor) {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  }).format(Number(valor || 0));
}

function textoSeguro(valor) {
  if (valor === null || valor === undefined) return '';
  return String(valor).trim();
}

function limparTexto(txt) {
  return textoSeguro(txt)
    .replace(/\r/g, '')
    .replace(/\*\*/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function numeroSeguroBR(valor) {
  if (valor === null || valor === undefined || valor === '') return 0;

  if (typeof valor === 'number') {
    return isNaN(valor) ? 0 : valor;
  }

  let texto = String(valor).trim().replace(/R\$\s?/gi, '').trim();

  if (texto.includes(',') && texto.includes('.')) {
    texto = texto.replace(/\./g, '').replace(',', '.');
  } else if (texto.includes(',')) {
    texto = texto.replace(',', '.');
  }

  texto = texto.replace(/[^\d.-]/g, '');

  const numero = Number(texto);
  return isNaN(numero) ? 0 : numero;
}

function ehLinhaTotal(item) {
  const texto = [
    item.categoria,
    item.item,
    item.descricao,
    item.justificativa,
    item.valor_total,
    item.referencia_preco
  ].map(v => String(v || '').toUpperCase()).join(' ');

  return (
    texto.includes('TOTAL GERAL') ||
    texto.includes('SUBTOTAL') ||
    texto.includes('TOTAL MATERIAIS') ||
    texto.includes('TOTAL RECURSOS') ||
    texto.includes('TOTAL EQUIPAMENTOS') ||
    texto.startsWith('TOTAL ')
  );
}

const dadosEntrada = $json;

const titulo_projeto = limparTexto(dadosEntrada.titulo_projeto) || 'Projeto';

const descricao_projeto =
  limparTexto(dadosEntrada.descricao_projeto) ||
  'A proposta foi estruturada com base nos itens e finalidades previstos na planilha orçamentária, organizando tecnicamente os recursos necessários para a execução das atividades do projeto.';

const objetivo_geral =
  limparTexto(dadosEntrada.objetivo_geral) ||
  'Estruturar e viabilizar a execução do projeto com base nos itens e finalidades previstos na planilha orçamentária.';

const justificativa =
  limparTexto(dadosEntrada.justificativa) ||
  'A proposta se justifica pela necessidade de estruturar adequadamente os recursos materiais, técnicos e operacionais indispensáveis à execução do projeto.';

let metodologia =
  limparTexto(dadosEntrada.metodologia) ||
  '2.5 METODOLOGIA:\nA execução do projeto será organizada a partir dos grupos de ações definidos com base nos itens da planilha orçamentária.';

/* =========================
PADRONIZAÇÃO DA METODOLOGIA
========================= */

metodologia = metodologia
  .replace(/Eixo\s+(\d+)\s*[—-]\s*/gi, '2.5.$1 ')
  .replace(/^METODOLOGIA:\s*/i, '2.5 METODOLOGIA:\n')
  .trim();

if (!/^2\.5\s+METODOLOGIA:?/i.test(metodologia)) {
  metodologia = `2.5 METODOLOGIA:\n${metodologia}`;
}

// 🔥 IMPORTANTE: NÃO formatar subitens tipo 2.5.1.1
metodologia = metodologia
  .replace(/\s+(2\.5\.\d+\s+)/g, '\n\n$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

/* =========================
OBJETIVOS ESPECÍFICOS
========================= */

let objetivosArray = [];

if (Array.isArray(dadosEntrada.objetivos_especificos_array)) {
  objetivosArray = dadosEntrada.objetivos_especificos_array
    .map(item => limparTexto(item))
    .filter(Boolean);
} else if (Array.isArray(dadosEntrada.objetivos_especificos)) {
  objetivosArray = dadosEntrada.objetivos_especificos
    .map(item => limparTexto(item))
    .filter(Boolean);
} else if (typeof dadosEntrada.objetivos_especificos === 'string') {
  objetivosArray = dadosEntrada.objetivos_especificos
    .split('\n')
    .map(item => limparTexto(item).replace(/^[-•\d.\)\s]+/, '').trim())
    .filter(Boolean);
}

if (!objetivosArray.length) {
  objetivosArray = [
    'Estruturar os recursos necessários para execução do projeto',
    'Organizar os insumos, equipamentos e materiais previstos',
    'Garantir condições técnicas e operacionais adequadas para o desenvolvimento das ações'
  ];
}

const objetivos_especificos = objetivosArray
  .map((obj, i) => {
    const texto = obj.replace(/^Objetivo Específico\s*\d+\s*[—-]\s*/i, '').trim();
    return `Objetivo Específico ${i + 1} — ${texto}`;
  })
  .join('\n');

/* =========================
CÁLCULO VALOR GLOBAL
========================= */

let itens = [];

try {
  const dadosAgrupados = $('Consolidar Itens da Planilha').first().json;
  itens = Array.isArray(dadosAgrupados.itens) ? dadosAgrupados.itens : [];
} catch (e) {
  itens = [];
}

let total = 0;
const itensSomados = [];
const itensIgnorados = [];

for (const item of itens) {
  if (ehLinhaTotal(item)) {
    itensIgnorados.push({
      motivo: 'Linha de total/subtotal ignorada',
      item: item.item || '',
      descricao: item.descricao || '',
      valor_total: item.valor_total || ''
    });
    continue;
  }

  const valor = numeroSeguroBR(item.valor_total);

  if (valor > 0) {
    total += valor;
    itensSomados.push({
      item: item.item || '',
      descricao: item.descricao || '',
      valor_total_original: item.valor_total || '',
      valor_convertido: valor
    });
  } else {
    itensIgnorados.push({
      motivo: 'Valor total vazio ou inválido',
      item: item.item || '',
      descricao: item.descricao || '',
      valor_total: item.valor_total || ''
    });
  }
}

total = Math.round(total * 100) / 100;

const valor_global = formatarMoedaBR(total);
const valor_global_numero = total;

/* =========================
HISTÓRICO DO PROPONENTE
========================= */

let historico_proponente = '';

try {
  const linha = $('Buscar Dados da Planilha').first().json;

  historico_proponente = limparTexto(
    linha.historico_proponente ??
    linha['HISTÓRICO DO PROPONENTE'] ??
    linha['HISTORICO DO PROPONENTE'] ??
    linha['historico do proponente']
  );
} catch (e) {
  historico_proponente = '';
}

/* =========================
PÚBLICO
========================= */

let publico_direto = limparTexto(dadosEntrada.publico_direto);
let publico_indireto = limparTexto(dadosEntrada.publico_indireto);

try {
  const linha = $('Buscar Dados da Planilha').first().json;

  if (!publico_direto) {
    publico_direto = limparTexto(
      linha.publico_direto ??
      linha['PÚBLICO DIRETO'] ??
      linha['PUBLICO DIRETO'] ??
      linha['publico direto']
    );
  }

  if (!publico_indireto) {
    publico_indireto = limparTexto(
      linha.publico_indireto ??
      linha['PÚBLICO INDIRETO'] ??
      linha['PUBLICO INDIRETO'] ??
      linha['publico indireto']
    );
  }
} catch (e) {}

/* =========================
RETORNO FINAL
========================= */

return [
  {
    json: {
      ...dadosEntrada,
      titulo_projeto,
      descricao_projeto,
      objetivo_geral,
      objetivos_especificos,
      objetivos_especificos_array: objetivosArray,
      justificativa,
      metodologia,
      historico_proponente,
      valor_global,
      valor_global_numero,
      publico_direto,
      publico_indireto,
      itens_somados_valor_global: itensSomados,
      itens_ignorados_valor_global: itensIgnorados,

      // 🔥 NOVO PADRÃO
      metodologia_fora_padrao: dadosEntrada.metodologia_fora_padrao || false,
      metodologia_invalida: dadosEntrada.metodologia_invalida || false,
      usa_subitens_de_produtos: dadosEntrada.usa_subitens_de_produtos || false,
      termos_indesejados_encontrados: dadosEntrada.termos_indesejados_encontrados || []
    }
  }
];

